    "content": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\"\n    xmlns:tools=\"http://schemas.android.com/tools\">\n\n    <!-- Camera hardware & features -->\n    <uses-feature\n        android:name=\"android.hardware.camera\"\n        android:required=\"true\" />\n    <uses-feature\n        android:name=\"android.hardware.camera.autofocus\"\n        android:required=\"false\" />\n    <uses-feature\n        android:name=\"android.hardware.location.gps\"\n        android:required=\"false\" />\n\n    <!-- Core Dashcam Permissions -->\n    <uses-permission android:name=\"android.permission.CAMERA\" />\n    <uses-permission android:name=\"android.permission.RECORD_AUDIO\" />\n    <uses-permission android:name=\"android.permission.ACCESS_FINE_LOCATION\" />\n    <uses-permission android:name=\"android.permission.ACCESS_COARSE_LOCATION\" />\n    <uses-permission android:name=\"android.permission.WAKE_LOCK\" />\n    <uses-permission android:name=\"android.permission.POST_NOTIFICATIONS\" />\n\n    <!-- Foreground Service (Android 14+ specific types) -->\n    <uses-permission android:name=\"android.permission.FOREGROUND_SERVICE\" />\n    <uses-permission android:name=\"android.permission.FOREGROUND_SERVICE_CAMERA\" />\n    <uses-permission android:name=\"android.permission.FOREGROUND_SERVICE_LOCATION\" />\n\n    <!-- Google Play Billing -->\n    <uses-permission android:name=\"com.android.vending.BILLING\" />\n\n    <application\n        android:name=\".RydeCamApplication\"\n        android:allowBackup=\"true\"\n        android:icon=\"@mipmap/ic_launcher\"\n        android:label=\"@string/app_name\"\n        android:roundIcon=\"@mipmap/ic_launcher_round\"\n        android:supportsRtl=\"true\"\n        android:theme=\"@style/Theme.RydeCam\"\n        tools:targetApi=\"35\">\n\n        <!-- Main Dashcam Activity -->\n        <activity\n            android:name=\".ui.MainActivity\"\n            android:exported=\"true\"\n            android:launchMode=\"singleTop\"\n            android:screenOrientation=\"unspecified\"\n            android:configChanges=\"orientation|screenSize|screenLayout|smallestScreenSize|keyboardHidden\"\n            android:supportsPictureInPicture=\"true\"\n            android:theme=\"@style/Theme.RydeCam\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.MAIN\" />\n                <category android:name=\"android.intent.category.LAUNCHER\" />\n            </intent-filter>\n        </activity>\n\n        <!-- Continuous Foreground Recording Service -->\n        <service\n            android:name=\".recording.DashcamRecordingService\"\n            android:exported=\"false\"\n            android:foregroundServiceType=\"camera|location\" />\n\n    </application>\n\n</manifest>\n"
